foreach v of var * {
local `v'_l: var label `v'
}
*
collapse $mgr $avg_employees $tot $share $estab $perf $outcome (first) ind* municipality* firm_code, by(e_id year)
*attach label 
foreach v of var * {
label var `v' `"``v'_l'"'
}

use "${final_data_folder}/clientelism_individual_data_stacked.dta", clear


** We want one point on the graph for every municipality-year, since that is the level at which the rainfall shock is measured
collapse ask_private_stacked rainfall_std_stacked rainfall_std_stacked_og, by(mun_id year2012)


#delimit ;

** Note: Do not standardize rainfall shock across municipalities;
scatter ask_private_stacked rainfall_std_stacked_og if year2012 == 1, 
msize(2) msymbol(O) ylabel(, labsize(small) angle(0)) xlabel(-0.7(0.35)0.7, labsize(small)) ||

scatter ask_private_stacked rainfall_std_stacked_og if year2012 == 0, 
msize(2) msymbol(T) mfcolor(white) ylabel(, labsize(small) angle(0)) xlabel(-0.7(0.35)0.7, labsize(small))

graphregion(color(white)) legend(label(1 "2012 observations") label(2 "2013 observations") size(small) symys(*.5) symxs(*.5)) 
ytitle("Proportion of respondents who requested a private good", size(small))
xtitle("Deviation from long-term average rainfall in municipality", size(small));

graph display, xsize(9.5) ysize(5.5);
graph export "${figures_folder}/Figure A1.pdf", replace as(pdf) name("Graph");


#delimit cr

// Estimation with eventstudyinteract of Sun and Abraham (2020)
sum Ei
gen lastcohort = Ei==r(max) // dummy for the latest- or never-treated cohort
forvalues l = 0/5 {
	gen L`l'event = K==`l'
}
forvalues l = 1/14 {
	gen F`l'event = K==-`l'
}
drop F1event // normalize K=-1 (and also K=-15) to zero
timer on 4
eventstudyinteract Y L*event F*event, vce(cluster i) absorb(i t) cohort(Ei) control_cohort(lastcohort)
timer off 4
event_plot e(b_iw)#e(V_iw), default_look graph_opt(xtitle("Periods since the event") ytitle("Average causal effect") xlabel(-9(1)4) ///
	title("Sun and Abraham (2020)")) stub_lag(L#event) stub_lead(F#event) together

if "`roundkeep'" == "r2r3r4" {
	drop if migrant_r3 ==. | migrant_r4 == .
	merge m:1 migrant_r3 migrant_r4 using type_merge_`roundkeep'.dta //`type_merge'
	}
else if "`roundkeep'" == "r2r4" {
	drop if migrant_r2 ==. | migrant_r4 == .
	merge m:1 migrant_r2 migrant_r4 using type_merge_`roundkeep'.dta //`type_merge'
	}

assert _merge == 3
drop _merge

#delimit;

//interact variables for test;
 foreach var in loss gain year2 {;
    gen `var'_K2 = `var' * gK2;
	gen `var'_38 = `var' * g38;
	gen `var'_ma = `var' * male;
	gen `var'_fe = `var' * female;
	gen `var'_bl = `var' * black;
	gen `var'_hi = `var' * hispanic;
	gen `var'_ab = `var' * above_math;
	gen `var'_be = `var' * below_math;
	gen `var'_aV = `var' * aV;
	gen `var'_bV = `var' * bV;
 };

foreach yr in 0 1 all{ ;

 	if "`yr'" == "0"{;
		local condition "year == 1";
		local yr_fix "";
		local controls "$oldX_vam";
	};
	else if "`yr'" == "1"{;
		local condition "year == 2";
		local yr_fix "";
		local controls "$oldX_vam t_gain_y1 t_loss_y1 t_nis_y1 lottery";
	};
	if "`yr'" == "all"{;
		local condition "1";
		local yr_fix "i.year";
		local controls "$oldX_vam_pool t_gain_y1 t_loss_y1 t_nis_y1 lottery";
	};

   cgmreg math_std loss_ma gain_ma loss_fe gain_fe `controls' `yr_fix' if `condition', cluster(teacher_id newstudid) ;
	test loss_ma = loss_fe;
	local p_l_gend_`yr' = string(r(p), "%4.3f") ;
	test gain_ma = gain_fe;
	local p_g_gend_`yr' = string(r(p), "%4.3f") ;


	cgmreg math_std loss_bl gain_bl loss_hi gain_hi `controls' `yr_fix' if `condition', cluster(teacher_id newstudid) ;
	test loss_bl = loss_hi;
	local p_l_race_`yr' = string(r(p), "%4.3f") ;
	test gain_bl = gain_hi;
	local p_g_race_`yr' = string(r(p), "%4.3f") ;


	cgmreg math_std loss_ab gain_ab loss_be gain_be `controls' `yr_fix' if `condition', cluster(teacher_id newstudid) ;
	test loss_ab = loss_be;
	local p_l_q_`yr' = string(r(p), "%4.3f") ;
	test gain_ab = gain_be;
	local p_g_q_`yr' = string(r(p), "%4.3f") ;


	cgmreg math_std loss_K2 gain_K2 loss_38 gain_38 `controls' `yr_fix' if `condition', cluster(teacher_id newstudid) ;
	test loss_K2 = loss_38;
	local p_l_grade_`yr' = string(r(p), "%4.3f") ;
	test gain_K2 = gain_38;
	local p_g_grade_`yr' = string(r(p), "%4.3f") ;

	cgmreg math_std loss_aV gain_aV loss_bV gain_bV `controls' `yr_fix' if `condition', cluster(teacher_id newstudid) ;
	test loss_aV = loss_bV;
	local p_l_aV_`yr' = string(r(p), "%4.3f") ;
	test gain_aV = gain_bV;
	local p_g_aV_`yr' = string(r(p), "%4.3f") ;

};
